import{_ as d,C as n,c,o as p,aj as h,G as a,j as e,w as r,a as o}from"./chunks/framework.Bfdr4H5E.js";const k=JSON.parse('{"title":"Deliberate Practice","description":"","frontmatter":{"outline":"deep","prev":{"text":"The Journey","link":"/trading-with-pav/the-journey"},"next":{"text":"Deliberate Practice Tools and Techniques","link":"/trading-with-pav/deliberate-practice-tools-and-techniques"}},"headers":[],"relativePath":"trading-with-pav/deliberate-practice.md","filePath":"trading-with-pav/deliberate-practice.md"}'),u={name:"trading-with-pav/deliberate-practice.md"};function m(f,t,b,g,v,w){const i=n("ProtectedPage"),l=n("GraphComment"),s=n("ClientOnly");return p(),c("div",null,[t[4]||(t[4]=h('<h1 id="deliberate-practice" tabindex="-1">Deliberate Practice <a class="header-anchor" href="#deliberate-practice" aria-label="Permalink to &quot;Deliberate Practice&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#effective-learning">Effective Learning</a></li><li><a href="#deliberate-practice-1">Deliberate Practice</a></li><li><a href="#trade–record–review-improve">Trade–Record–Review-Improve</a><ul><li><a href="#trade">Trade</a></li><li><a href="#record">Record</a></li><li><a href="#review">Review</a></li><li><a href="#improve">Improve</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="effective-learning" tabindex="-1">Effective Learning <a class="header-anchor" href="#effective-learning" aria-label="Permalink to &quot;Effective Learning&quot;">​</a></h2><p>We’ve clearly established earlier that trading success does not come from any special set of rules or indicators.</p><p>Rather it comes from an ability to read the price action, identifying signs of strength and weakness, understanding what that means, projecting that forward to identify potential future price action, and being able to take advantage of the areas of wholesale trade opportunity within that action. It’s a dynamic, subjective and largely intuitive process.</p><p>Achieving mastery of that process is the result of <strong>deliberate practice</strong>.</p><h2 id="deliberate-practice-1" tabindex="-1">Deliberate Practice <a class="header-anchor" href="#deliberate-practice-1" aria-label="Permalink to &quot;Deliberate Practice&quot;">​</a></h2><p>Deliberate practice, also referred to as Deep Practice, is a motivated, solution-focused process of seeking improvement in any performance related activity.</p><p>It is practice, over and over again, in which we act, receive feedback on our results, identify potential improvement and then repeat.</p><p>As Daniel Coyle says in “The Talent Code”:<br> “Deep practice is not simply about struggling; it’s about seeking out a particular struggle, which involves a cycle of distinct actions“.</p><ol><li>Pick a target.</li><li>Reach for it.</li><li>Evaluate the gap between the target and the reach.</li><li>Return to setup one.</li></ol><p>Essentially, it’s a process of repeated exposure combined with a process of trial and error.</p><p>Most people accept that riding a bike is simple. But only because you went through the learning process of trial and error – falling off many times and getting back on.</p><p>Trading is the same. Maximize exposure; and learn through a process of trial and error.</p><p>The concept of deliberate practice is well demonstrated in this great extract from an SMB Capital blog post:</p><blockquote><p>“… these patterns are most useful if you own them and make them your own. I have trained traders in the past and one of the exercises I had them do was literally to find several hundred examples of support / resistance both holding and failing on daily charts, and then to examine price action on intraday charts around those levels. You really do have to see many hundreds of patterns before you are comfortable with all the variations of holding and failing (and then failures of failures). I do not believe it is constructive, or even possible, to catalog all of the possible variations, but intuition will slowly grow from repeated exposure. Be aware that there is a tremendous difference between understanding patterns and trading, and this is but one of many important elements of price action.”</p><p>Refer to “Cambridge Handbook of Expertise and Export Performance” by Anders Ericsson for more detailed study, or “<a href="https://amzn.to/3oG63P8" target="_blank" rel="noreferrer">The Talent Code</a>” by Daniel Coyle for a great, easy to read introduction.<br><a href="http://www.smbtraining.com/blog/will-support-hold-or-fail-price-rejection-can-usually-tell-the-tale" target="_blank" rel="noreferrer">http://www.smbtraining.com/blog/will-support-hold-or-fail-price-rejection-can-usually-tell-the-tale</a></p></blockquote><h2 id="trade–record–review-improve" tabindex="-1">Trade–Record–Review-Improve <a class="header-anchor" href="#trade–record–review-improve" aria-label="Permalink to &quot;Trade–Record–Review-Improve&quot;">​</a></h2><p>As professional traders, we aim to implement deliberate practice into our daily routines. Not just during your learning phase, but continuing throughout your whole career. After all, in this game your learning will never end.</p><p>We do that through what I refer to as a <em>Trade-Record-Review-Improve</em> cycle.</p><h3 id="trade" tabindex="-1">Trade <a class="header-anchor" href="#trade" aria-label="Permalink to &quot;Trade&quot;">​</a></h3>',20)),a(i,null,{default:r(()=>t[0]||(t[0]=[e("div",{class:"info custom-block"},[e("p",{class:"custom-block-title"},"Step 1"),e("p",null,"Self-explanatory… trade the markets in accordance with your trading plan and procedures manual.")],-1)])),_:1,__:[0]}),t[5]||(t[5]=e("h3",{id:"record",tabindex:"-1"},[o("Record "),e("a",{class:"header-anchor",href:"#record","aria-label":'Permalink to "Record"'},"​")],-1)),a(i,null,{default:r(()=>t[1]||(t[1]=[e("div",{class:"tip custom-block"},[e("p",{class:"custom-block-title"},"Step 2"),e("p",null,"Record results in your trading logs and journals.")],-1)])),_:1,__:[1]}),t[6]||(t[6]=e("h3",{id:"review",tabindex:"-1"},[o("Review "),e("a",{class:"header-anchor",href:"#review","aria-label":'Permalink to "Review"'},"​")],-1)),a(i,null,{default:r(()=>t[2]||(t[2]=[e("div",{class:"warning custom-block"},[e("p",{class:"custom-block-title"},"Step 3"),e("p",null,"Review your results, considering the four key questions:"),e("ul",null,[e("li",null,"a. What did you expect to happen?"),e("li",null,"b. What did happen?"),e("li",null,"c. Why was there a difference?"),e("li",null,"d. What can you learn from this?")])],-1)])),_:1,__:[2]}),t[7]||(t[7]=e("h3",{id:"improve",tabindex:"-1"},[o("Improve "),e("a",{class:"header-anchor",href:"#improve","aria-label":'Permalink to "Improve"'},"​")],-1)),a(i,null,{default:r(()=>t[3]||(t[3]=[e("div",{class:"danger custom-block"},[e("p",{class:"custom-block-title"},"Step 4"),e("p",null,"Implement improvements, either through setting process goals for the next trading session, or through amendment to the trading plan and/or procedures manual.")],-1)])),_:1,__:[3]}),t[8]||(t[8]=e("p",null,"In next article will explore tools and techniques for deliberate practice.",-1)),t[9]||(t[9]=e("h2",{id:"comments",tabindex:"-1"},[o("Comments "),e("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),a(s,null,{default:r(()=>[a(l)]),_:1})])}const x=d(u,[["render",m]]);export{k as __pageData,x as default};
